package org.eclipse.rdf4j.federated.util;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

import org.eclipse.rdf4j.federated.algebra.ConjunctiveFilterExpr;
import org.eclipse.rdf4j.federated.algebra.FilterExpr;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.query.algebra.Compare.CompareOp;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.algebra.ValueExprTripleRef;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractSimpleQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

public class FilterUtilTest {

	@Test
	public void testConjunctiveFilterExpr() throws Exception {

		FilterExpr left = createFilterExpr("age", 15, CompareOp.GT);
		FilterExpr right = createFilterExpr("age", 25, CompareOp.LT);
		ConjunctiveFilterExpr expr = new ConjunctiveFilterExpr(left, right);

		Assertions.assertEquals(
				"( ( ?age > '15'^^<http://www.w3.org/2001/XMLSchema#int> ) && ( ?age < '25'^^<http://www.w3.org/2001/XMLSchema#int> ) )",
				FilterUtils.toSparqlString(expr));
	}

	@Test
	public void testDirectedLanguageLiteral() throws Exception {
		Literal literal = Values.getValueFactory().createLiteral("שלום", "he", Literal.BaseDirection.RTL);
		FilterExpr expr = new FilterExpr(new Compare(Var.of("label"), new ValueConstant(literal), CompareOp.EQ),
				new HashSet<>());

		Assertions.assertEquals("( ?label = 'שלום'@he--rtl )", FilterUtils.toSparqlString(expr));
	}

	@Test
	public void quotedFilterLiteralCannotEscapePushedDownExpression() throws Exception {
		Literal literal = Values.literal("O'Brien \\ newline\n control\u0001");
		FilterExpr expr = new FilterExpr(new Compare(Var.of("label"), new ValueConstant(literal), CompareOp.EQ),
				new HashSet<>());
		String query = "SELECT * WHERE { ?s <urn:p> ?label . FILTER " + FilterUtils.toSparqlString(expr) + " }";

		Assertions.assertTrue(parseConstants(query).contains(literal));
	}

	@Test
	public void filterRejectsMalformedLanguageTag() {
		Literal literal = SimpleValueFactory.getInstance().createLiteral("label", "en> ; DROP ALL");
		FilterExpr expr = new FilterExpr(new Compare(Var.of("label"), new ValueConstant(literal), CompareOp.EQ),
				new HashSet<>());

		Assertions.assertThrows(IllegalArgumentException.class, () -> FilterUtils.toSparqlString(expr));
	}

	@Test
	public void nestedTripleTermConstantKeepsItsLiteralInsideFilter() throws Exception {
		TripleTerm inner = Values.getValueFactory()
				.createTripleTerm(Values.iri("urn:s"), Values.iri("urn:p"),
						Values.literal("O'Brien"));
		TripleTerm outer = Values.getValueFactory().createTripleTerm(Values.iri("urn:s"), Values.iri("urn:p"), inner);
		FilterExpr expr = new FilterExpr(new Compare(Var.of("term"), new ValueConstant(outer), CompareOp.EQ),
				new HashSet<>());
		String query = "SELECT * WHERE { ?s <urn:p> ?term . FILTER " + FilterUtils.toSparqlString(expr) + " }";

		List<Compare> comparisons = new ArrayList<>();
		QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null)
				.getTupleExpr()
				.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Compare compare) {
						comparisons.add(compare);
						super.meet(compare);
					}
				});
		Assertions.assertEquals(1, comparisons.size());
		ValueExprTripleRef outerRef = Assertions.assertInstanceOf(ValueExprTripleRef.class,
				comparisons.get(0).getRightArg());
		Assertions.assertEquals(outer.getSubject(), outerRef.getSubjectVar().getValue());
		Assertions.assertEquals(outer.getPredicate(), outerRef.getPredicateVar().getValue());
		ValueExprTripleRef innerRef = Assertions.assertInstanceOf(ValueExprTripleRef.class, outerRef.getObjectExpr());
		Assertions.assertEquals(inner.getSubject(), innerRef.getSubjectVar().getValue());
		Assertions.assertEquals(inner.getPredicate(), innerRef.getPredicateVar().getValue());
		Assertions.assertEquals(inner.getObject(), innerRef.getObjectVar().getValue());
	}

	private List<Value> parseConstants(String query) {
		List<Value> values = new ArrayList<>();
		QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null)
				.getTupleExpr()
				.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(ValueConstant constant) {
						values.add(constant.getValue());
						super.meet(constant);
					}
				});
		return values;
	}

	private FilterExpr createFilterExpr(String leftVarName, int rightConstant, CompareOp operator) {
		Compare compare = new Compare(Var.of(leftVarName), valueConstant(rightConstant), operator);
		return new FilterExpr(compare, new HashSet<>());

	}

	private ValueExpr valueConstant(int constant) {
		return new ValueConstant(FedXUtil.valueFactory().createLiteral(constant));
	}
}
